def combine(n: int, k: int) -> list[list[int]]:
    res = []
    def backtrack(start, curr):
        if len(curr) == k:
            res.append(list(curr))
            return
        need = k - len(curr)
        for i in range(start, n - need + 2):
            curr.append(i)
            backtrack(i + 1, curr)
            curr.pop()
    backtrack(1, [])
    return res

